import React, { useState, useEffect } from 'react';
import './CartPage.css';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const CartPage = () => {
    const [items, setItems] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchCart = async () => {
            try {
                const userId = "USER_ID_HERE"; // Replace with actual logged-in user ID
                const response = await axios.get(`http://localhost:5000/cart/${userId}`);
                if (response.data.success) {
                    setItems(response.data.cart);
                } else {
                    console.error('Failed to fetch cart items');
                }
                setLoading(false);
            } catch (error) {
                console.error('Error fetching cart:', error);
                setLoading(false);
            }
        };

        fetchCart();
    }, []);

    const incrementQuantity = async (itemId) => {
        try {
            const updatedItems = items.map(item => 
                item.itemId === itemId ? { ...item, quantity: item.quantity + 1 } : item
            );
            setItems(updatedItems);
            await updateCartBackend(itemId, 1);
        } catch (error) {
            console.error('Error incrementing quantity:', error);
        }
    };

    const decrementQuantity = async (itemId) => {
        const item = items.find(item => item.itemId === itemId);
        if (item.quantity === 1) {
            const confirmDelete = window.confirm(`Are you sure you want to remove ${item.name} from the cart?`);
            if (!confirmDelete) return;
        }
        const updatedItems = items
            .map(item =>
                item.itemId === itemId ? { ...item, quantity: item.quantity - 1 } : item
            )
            .filter(item => item.quantity > 0);
        setItems(updatedItems);

        try {
            await updateCartBackend(itemId, -1);
        } catch (error) {
            console.error('Error decrementing quantity:', error);
        }
    };

    const updateCartBackend = async (itemId, change) => {
        const userId = "USER_ID_HERE"; // Replace with actual logged-in user ID
        await axios.post('http://localhost:5000/cart/add', {
            userId,
            itemId,
            quantity: change,
        });
    };

    const subtotal = items.reduce((total, item) => total + item.price * item.quantity, 0);

    if (loading) return <div>Loading...</div>;

    return (
        <div className="cart-container">
            <div className="cart-items">
                <h2>MY CART</h2>
                {items.length === 0 ? (
                    <p>Your cart is empty.</p>
                ) : (
                    items.map(item => (
                        <div key={item.itemId} className="item">
                            <img src={item.images[0]} alt={item.name} className="item-image" />
                            <div className="item-details">
                                <p className="item-name">{item.name}</p>
                                <div className="quantity-control">
                                    <button className="quantity-button" onClick={() => decrementQuantity(item.itemId)}>-</button>
                                    <span className="quantity">{item.quantity}</span>
                                    <button className="quantity-button" onClick={() => incrementQuantity(item.itemId)}>+</button>
                                </div>
                            </div>
                        </div>
                    ))
                )}
            </div>
            {items.length > 0 && (
                <div className="cart-subtotal">
                    <h2>CART SUBTOTAL</h2>
                    <div className="total">SUBTOTAL: ₹{subtotal}</div>
                    <button className="checkout-button">Checkout</button>
                </div>
            )}
        </div>
    );
};

export default CartPage;
